const std::vector<LevelCalibration>& calibration_table() {
  return kCalibratedTable;
}

const LevelCalibration& find_calibration(std::string_view instrument_name,
                                         std::string_view family,
                                         int program) {
  const std::string lowered_name = lower_copy(instrument_name);
  const std::string lowered_fam = lower_copy(family);

  // 1. 精确名称或别名匹配
  for (const auto& item : kCalibratedTable) {
    if (lower_copy(item.name) == lowered_name) return item;
  }
  // 特殊声部名子串匹配
  for (const auto& item : kCalibratedTable) {
    const std::string key = lower_copy(item.name);
    if (!lowered_name.empty() && (lowered_name.find(key) != std::string::npos || key.find(lowered_name) != std::string::npos)) {
      return item;
    }
  }
  // 2. GM 回退程序匹配
  if (program == 21 || lowered_name.find("accordion") != std::string::npos) {
    for (const auto& item : kCalibratedTable) if (item.name == "Accordion") return item;
  }
  if (program == 4 || program == 5) {
    for (const auto& item : kCalibratedTable) if (item.name == "Electric Piano") return item;
  }
  // 3. 家族默认
  for (const auto& def : kFamilyDefaults) {
    if (def.family == lowered_fam) return def;
  }
  return kDefaultCalibration;
}

